solution.solution.cpp:
#include <algorithm>

class FixedStepClock
{
public:
    FixedStepClock(double step, double maxFrame) : m_step{ step }, m_maxFrame{ maxFrame } {}

    int advance(double frameTime)
    {
        m_accumulator += std::min(std::max(frameTime, 0.0), m_maxFrame);
        int updates{ 0 };
        // A tiny tolerance so that, for example, 0.005 + 0.005 counts as one 0.01 step.
        while (m_accumulator >= m_step - 1e-12)
        {
            m_accumulator -= m_step;
            ++updates;
        }
        if (m_accumulator < 0) m_accumulator = 0;
        return updates;
    }

    double alpha() const { return m_accumulator / m_step; }

private:
    double m_step;
    double m_maxFrame;
    double m_accumulator{ 0.0 };
};

double interpolate(double previous, double current, double alpha)
{
    return previous + (current - previous) * alpha;
}

unitTests:
TEST("the example")
{
    FixedStepClock clock{ 0.01, 0.25 };
    CHECK_EQ(clock.advance(0.025), 2);
    CHECK_NEAR(clock.alpha(), 0.5, 1e-9);
    CHECK_EQ(clock.advance(0.005), 1);
    CHECK_NEAR(clock.alpha(), 0.0, 1e-9);
    CHECK_EQ(clock.advance(5.0), 25);
}
TEST("short frames accumulate") { FixedStepClock c{ 0.25, 1.0 }; CHECK_EQ(c.advance(0.125), 0); CHECK_NEAR(c.alpha(), 0.5, 1e-12); CHECK_EQ(c.advance(0.125), 1); CHECK_NEAR(c.alpha(), 0.0, 1e-12); }
TEST("the cap") { FixedStepClock c{ 0.5, 1.0 }; CHECK_EQ(c.advance(100.0), 2); }
TEST("negative frame times are ignored") { FixedStepClock c{ 0.5, 1.0 }; CHECK_EQ(c.advance(-3.0), 0); CHECK_NEAR(c.alpha(), 0.0, 1e-12); }
TEST("interpolation") { CHECK_NEAR(interpolate(10, 20, 0.25), 12.5, 1e-12); CHECK_NEAR(interpolate(10, 20, 0), 10, 1e-12); CHECK_NEAR(interpolate(-4, 4, 0.5), 0, 1e-12); }
TEST("sixty hertz for one second") { FixedStepClock c{ 1.0 / 60.0, 0.25 }; int total{ 0 }; for (int i{ 0 }; i < 100; ++i) total += c.advance(0.01); CHECK(total >= 59 && total <= 60); }

